The Newton--Coulomb stationary quantum gravity\index{Newton--Coulomb quantum gravity!stationary}, defined by the effective gravitational potential\index{gravitational potential!effective} $V_{eff}[h]=\dfrac{a_{-1}}{h}$, determines the three-dimensional embedded spaces which are the maximally symmetric three-dimensional Einstein manifolds\index{Einstein manifolds}, characterized by the sign of the form (\ref{sign}). There is the classification of such manifolds with respect to the cosmological constant\index{cosmological constant} $\Lambda$ and the value $a_{-1}$ of the residue of the effective gravitational potential\index{gravitational potential!effective}
\begin{enumerate}
\item If the sign of manifold is non-zero $\lambda\neq0$ and the residue of the effective gravitational potential\index{gravitational potential!effective} is a negative real $a_{-1}=-|\alpha|$, then the effective gravitational potential\index{gravitational potential!effective} $V_{eff}[h]$ corresponds to the Newtonian attractive potential energy
    \begin{equation}
    V_{eff}=-\dfrac{|\alpha|}{h}\sim-\dfrac{m_1m_2}{h}.\label{i1}
    \end{equation}
    \begin{enumerate}
      \item If the cosmological constant\index{cosmological constant} is a positive real $\Lambda=+|\Lambda|$ then the maximally symmetric Einstein three-manifolds are characterized by the positive Ricci scalar curvature\index{Ricci scalar curvature}
    \begin{equation}
    {^{(3)}}R=\dfrac{2}{3}|\Lambda|+2\kappa^2|\alpha|.
    \end{equation}
    \item If the cosmological constant\index{cosmological constant} is a negative real $\Lambda=-|\Lambda|$ then the maximally symmetric Einstein three-manifolds are characterized by the Ricci scalar curvature\index{Ricci scalar curvature}
    \begin{equation}
    {^{(3)}}R=-\dfrac{2}{3}|\Lambda|+2\kappa^2|\alpha|,
    \end{equation}
    which is
    \begin{equation}
      {^{(3)}}R\left\{\begin{array}{ccc}
        <0,&\textrm{iff}&|\Lambda|>3\kappa^2|\alpha|\\
        =0,&\textrm{iff}&|\Lambda|=\kappa^2|\alpha|\\
        >0,&\textrm{iff}&|\Lambda|<3\kappa^2|\alpha|
      \end{array}\right.
    \end{equation}
    \end{enumerate}
\item If the sign of manifold is non-zero $\lambda\neq0$ and the residue of the effective gravitational potential\index{gravitational potential!effective} is a positive real $a_{-1}=+|\alpha|$, then the effective potential $V_{eff}[h]$ becomes the Coulomb repulsive potential energy
    \begin{equation}
    V_{eff}=\dfrac{|\alpha|}{h}\sim\dfrac{q_1q_2}{h}.\label{i2}
    \end{equation}
    \begin{enumerate}
      \item If the cosmological constant\index{cosmological constant} is a negative real $\Lambda=-|\Lambda|$ then the maximally symmetric Einstein three-manifolds are characterized by negative Ricci scalar curvature\index{Ricci scalar curvature}
    \begin{equation}
      {^{(3)}}R=-\dfrac{2}{3}|\Lambda|-2\kappa^2|\alpha|.
    \end{equation}
    \item If the cosmological constant\index{cosmological constant} is a positive real $\Lambda=+|\Lambda|$ then the maximally symmetric Einstein three-manifolds are characterized by the Ricci scalar curvature\index{Ricci scalar curvature}
    \begin{equation}
      {^{(3)}}R=\dfrac{2}{3}|\Lambda|-2\kappa^2|\alpha|,
    \end{equation}
    which is
    \begin{equation}
      {^{(3)}}R\left\{\begin{array}{ccc}
        <0,&\textrm{iff}&|\Lambda|<3\kappa^2|\alpha|\\
        =0,&\textrm{iff}&|\Lambda|=\kappa^2|\alpha|\\
        >0,&\textrm{iff}&|\Lambda|>3\kappa^2|\alpha|
      \end{array}\right.
    \end{equation}
    \end{enumerate}
\item If the sign of manifold is identically vanishing $\lambda=0$, \emph{i.e.} the maximally symmetric Einstein three-manifolds\index{Einstein manifolds} are Ricci-flat\index{Ricci-flat manifold} manifolds, then one can determine uniquely the value of the residue of the effective gravitational potential\index{gravitational potential!effective} as follows
    \begin{equation}
    a_{-1}=\pm\dfrac{|\Lambda|}{3\kappa^2}.\label{i3}
    \end{equation}
    In such a situation, one obtains the values of the cosmological constant\index{cosmological constant}
\begin{equation}\label{lambda}
  |\Lambda|\sim\left\{\begin{array}{rl}r_g(m_1)r_g(m_2)&\mathrm{for~the~Newton~law}\vspace*{10pt}\\
  r_e(q_1)r_e(q_2)&\mathrm{for~the~Coulomb~law}\end{array}\right.
\end{equation}
where $m$ is the mass of a body generating Newtonian gravitational field in vacuum and $r_g(m)=\dfrac{2Gm}{c^2}$ is its gravitational radius, $q$ is the charge generating Coulombic electrical field in vacuum and $r_e(q)=q\sqrt{\dfrac{G}{4\pi \epsilon_0c^4}}$ is its electrical radius.
\end{enumerate}
